insert into public.test_knowledge (subjects, grade_min, grade_max, kind, title, body, source_url, status, origin, verified_at) values
  ('{geography}', 9, 12, 'rule', 'Mapwork: gradient', 'Gradient = vertical interval (VI) ÷ horizontal equivalent (HE), written as a ratio 1 : n (divide HE by VI to get n). VI is the difference in height between the two points. HE is the real distance on the ground, in the same unit as VI (metres). The smaller the n, the steeper the slope.', 'https://www.education.gov.za/Portals/0/CD/Computer/Self-Study_Geography_Mapwork_Gr_10-12.pdf', 'approved', 'seed', now()),
  ('{geography}', 9, 12, 'rule', 'Mapwork: real distance from the map', 'Real distance = map distance × scale denominator. On a 1:50 000 map, 1 cm on the map is 50 000 cm = 500 m = 0,5 km on the ground. Measure the map distance in cm or mm, then convert (100 000 cm = 1 km). On a 1:10 000 orthophoto map, 1 cm is 100 m.', 'https://www.graemecollege.co.za/media/1225/mapwork-calculations.pdf', 'approved', 'seed', now()),
  ('{geography}', 9, 12, 'fact', 'Topographic and orthophoto maps', 'The South African topographic map is at a scale of 1:50 000 with a contour interval of 20 m. The orthophoto map is at 1:10 000 (an aerial photograph with contours added). The 1:50 000 map covers a larger area with less detail, so it is the smaller scale. Index contours are the heavier numbered contour lines. A spot height is a point with its exact height. A trigonometrical (trig) beacon marks a surveyed height.', 'https://pt.slideshare.net/slideshow/geography-mapwork-revision-grades-10-12-ismail-m-pptx/289464563', 'approved', 'seed', now()),
  ('{geography}', 10, 12, 'rule', 'Mapwork: vertical exaggeration', 'Vertical exaggeration (VE) = vertical scale (VS) ÷ horizontal scale (HS), with both scales written in the same units as fractions. Example: VS 1 cm = 20 m = 1 : 2 000 and HS 1 : 50 000 give VE = 50 000 ÷ 2 000 = 25 times. It is used in cross-sections to show hills and valleys more clearly.', 'https://www.graemecollege.co.za/media/1225/mapwork-calculations.pdf', 'approved', 'seed', now()),
  ('{natural sciences,natural science,science}', 7, 9, 'fact', 'Natural Sciences knowledge strands', 'CAPS Natural Sciences Grades 7 to 9 is organised into four knowledge strands: Life and Living; Matter and Materials; Energy and Change; Planet Earth and Beyond. Use these names, and keep questions to what the grade covers.', 'https://timssandpirls.bc.edu/timss2015/encyclopedia/countries/south-africa/the-science-curriculum-in-primary-and-lower-secondary-grades/', 'approved', 'seed', now()),
  ('{mathematics,maths,math}', 7, 12, 'rule', 'Properties of numbers', 'Commutative: a + b = b + a and a × b = b × a. Associative: (a + b) + c = a + (b + c) and (a × b) × c = a × (b × c). Distributive: a × (b + c) = a × b + a × c. Subtraction and division are NOT commutative or associative.', 'https://assets.cambridge.org/97811087/65695/excerpt/9781108765695_excerpt.pdf', 'approved', 'seed', now()),
  ('{mathematics,maths,math}', 4, 12, 'rule', 'Maths conventions in South Africa', 'Use a decimal comma (3,5 not 3.5) and a space for thousands (12 500). Always work out calculations step by step and make sure exactly one option or answer is correct. Rounding to the nearest ten, hundred or thousand looks at the digit one place to the right (5 or more rounds up).', null, 'approved', 'seed', now()),
  ('{natural sciences,physical sciences,science}', 7, 12, 'rule', 'SI units and common formulas', 'Use SI units: metre (m), kilogram (kg), second (s), newton (N), joule (J), watt (W), volt (V), ampere (A), ohm (Ω). speed = distance ÷ time. density = mass ÷ volume. force of weight = mass × 9,8 m·s⁻² (g = 9,8 m·s⁻² in CAPS). V = I × R. Never mix up mass (kg) and weight (N).', null, 'approved', 'seed', now()),
  ('{life sciences,natural sciences}', 7, 12, 'rule', 'Biology accuracy', 'Only name structures and functions you are certain of. A cell membrane controls what enters and leaves; the nucleus holds the DNA; mitochondria release energy by respiration; chloroplasts (plant cells) carry out photosynthesis; the cell wall is in plant cells, not animal cells. Photosynthesis: carbon dioxide + water → glucose + oxygen, using light energy and chlorophyll.', null, 'approved', 'seed', now())
